 87	async function listDoSessions(registeredWorkDirs: string[]): Promise<SessionInfo[]> {
 88	  const sessions: SessionInfo[] = [];
 89	  const seen = new Set<string>();
 90	
 91	  // Helper: scan a directory for Do session subdirs
 92	  async function scanDir(baseDir: string, labelPrefix: string): Promise<void> {
 93	    if (!fs.existsSync(baseDir)) return;
 94	    const entries = await fs.promises.readdir(baseDir, { withFileTypes: true });
 95	    for (const e of entries) {
 96	      if (!e.isDirectory()) continue;
 97	      if (!UUID_REGEX.test(e.name)) continue;
 98	      if (seen.has(e.name)) continue;
 99	      seen.add(e.name);
100	
101	      const journalPath = path.join(baseDir, e.name, "journal.jsonl");
102	      if (!fs.existsSync(journalPath)) continue;
103	
104	      try {
105	        const st = await fs.promises.stat(journalPath);
106	        const brief = await getFirstWorkDirFromDoJournal(journalPath);
107	        sessions.push({
108	          id: e.name,
109	          workDir: brief ? `[Do] ${path.basename(brief)}` : `${labelPrefix}${e.name}`,
110	          updatedAt: st.mtimeMs || st.mtime.getTime(),
111	          contextFile: journalPath,
112	          brief: brief || DEFAULT_FALLBACK_TITLE,
113	          isThinking: false,
114	        });
115	      } catch {
116	        // skip corrupted sessions
117	      }
118	    }
119	  }
120	
121	  // 1. Scan old global path (legacy sessions from before Phase 09)
122	  await scanDir(getDoSessionsDir(), "[Do Legacy] ");
123	
124	  // 2. Scan new workspace-local paths for each registered work dir
125	  for (const wd of registeredWorkDirs) {
126	    const wdDir = getWorkspaceDoDir(wd);
127	    await scanDir(wdDir, `[Do ${path.basename(wd)}] `);
128	  }
129	
130	  return sessions.sort((a, b) => b.updatedAt - a.updatedAt);
131	}
