134	  [Methods.GetConsiliumSessions]: async (_, ctx) => {
135	    if (!ctx.workDir) return [];
136	    const sessions = await listSessions(ctx.workDir);
137	    for (const s of sessions) {
138	      const meta = ctx.getSessionMetadata(s.id);
139	      s.brief = meta?.title || s.brief;
140	      (s as any).mode = meta?.mode || 'legacy';
