218	  [Methods.SetWorkDir]: async (params: { workDir: string | null }, ctx) => {
219	    if (!ctx.workspaceRoot) {
220	      return { ok: false };
221	    }
222	    const target = params.workDir;
223	    if (target && target !== ctx.workspaceRoot && !target.startsWith(ctx.workspaceRoot + path.sep)) {
224	      return { ok: false };
225	    }
226	    ctx.setCustomWorkDir(target);
227	    return { ok: true, workDir: target || ctx.workspaceRoot };
228	  },
