438	    if (!ctx.workDir || !UUID_REGEX.test(params.sessionId) || params.turnIndex < 0) {
439	      return null;
440	    }
441	    try {
442	      return await forkSession({
443	        workDir: ctx.workDir,
444	        sourceSessionId: params.sessionId,
445	        turnIndex: params.turnIndex,
