 1	import * as path from "node:path";
 2	import * as os from "node:os";
 3	import * as crypto from "node:crypto";
 4	
 5	function hashPath(workDir: string): string {
 6	  return crypto.createHash("md5").update(workDir, "utf-8").digest("hex");
 7	}
 8	
 9	export interface ConsiliumPathsType {
10	  home: string;
11	  config: string;
12	  mcpConfig: string;
13	  sessionsDir(workDir: string): string;
14	  sessionDir(workDir: string, sessionId: string): string;
15	  baselineDir(workDir: string, sessionId: string): string;
16	}
