 22	function readSessionMetadata(sessionDir: string): { title?: string } | null {
 23	  try {
 24	    return JSON.parse(fs.readFileSync(path.join(sessionDir, "metadata.json"), "utf-8"));
 25	  } catch {
 26	    return null;
 27	  }
 28	}
