 46	/** Get all workDirs registered under a workspace (from consilium.json) */
 47	export function getRegisteredWorkDirs(workspaceRoot: string): string[] {
 48	  const config = readConsiliumJson();
 49	  if (!config?.work_dirs) {
 50	    return [workspaceRoot];
 51	  }
 52	
 53	  const sep = path.sep;
 54	  // On Windows, drive-letter casing can differ (C:\ vs c:\) and produce
 55	  // different session hashes. Use case-insensitive comparison so sessions
 56	  // stored under either variant are discoverable.
 57	  const isWindows = process.platform === "win32";
 58	  const normalize = isWindows ? (s: string) => s.toLowerCase() : (s: string) => s;
 59	  const normWorkspaceRoot = normalize(workspaceRoot);
 60	
 61	  const dirs = config.work_dirs
 62	    .map((e) => e.path)
 63	    .filter((p) => {
 64	      const normPath = normalize(p);
 65	      return normPath === normWorkspaceRoot || normPath.startsWith(normWorkspaceRoot + sep);
 66	    });
 67	
 68	  return dirs.length > 0 ? dirs : [workspaceRoot];
 69	}
 70	
 71	/** List sessions from all registered workDirs under a workspace */
 72	export async function listSessionsForWorkspace(workspaceRoot: string): Promise<SessionInfo[]> {
 73	  const workDirs = getRegisteredWorkDirs(workspaceRoot);
 74	  const allSessions: SessionInfo[] = [];
 75	
 76	  for (const workDir of workDirs) {
 77	    const sessions = await listSessions(workDir);
 78	    allSessions.push(...sessions);
 79	  }
 80	
 81	  // Also include Think sessions so they appear in the history list
 82	  const thinkSessions = await listThinkSessions(workspaceRoot);
 83	  allSessions.push(...thinkSessions);
 84	
 85	  return allSessions.sort((a, b) => b.updatedAt - a.updatedAt);
 86	}
