147	// List Sessions (Async)
148	export async function listSessions(workDir: string): Promise<SessionInfo[]> {
149	  const sessionsDir = ConsiliumPaths.sessionsDir(workDir);
150	
151	  try {
152	    await fsp.access(sessionsDir);
153	  } catch {
154	    return [];
155	  }
156	
157	  let entries: fs.Dirent[];
158	  try {
159	    entries = await fsp.readdir(sessionsDir, { withFileTypes: true });
160	  } catch (err) {
161	    console.warn("[storage] Failed to read sessions:", err);
162	    return [];
163	  }
164	
165	  const sessions: SessionInfo[] = [];
166	
167	  for (const entry of entries) {
168	    if (!entry.isDirectory() || !UUID_REGEX.test(entry.name)) {
169	      continue;
170	    }
171	
172	    const sessionId = entry.name;
173	    const sessionDir = path.join(sessionsDir, sessionId);
174	    const wireFile = path.join(sessionDir, "wire.jsonl");
175	
176	    if (!fs.existsSync(wireFile)) {
177	      continue;
178	    }
179	
180	    try {
181	      const stat = await fsp.stat(wireFile);
182	      if (stat.size === 0) {
183	        continue;
184	      }
185	
186	      // Priority: metadata.json > wire.jsonl
187	      const metadata = readSessionMetadata(sessionDir);
188	      const brief = metadata?.title || (await getFirstUserMessage(wireFile));
189	      if (!brief) {
190	        continue;
191	      }
192	
193	      sessions.push({
194	        id: sessionId,
195	        workDir,
196	        contextFile: wireFile,
197	        updatedAt: stat.mtimeMs,
198	        brief,
199	        isThinking: false,
200	      });
201	    } catch (err) {
202	      log.storage("Failed to stat session %s: %O", sessionId, err);
203	    }
204	  }
205	
206	  return sessions.sort((a, b) => b.updatedAt - a.updatedAt);
207	}
