229	// Get First User Message (Stream-based, early exit)
230	async function getFirstUserMessage(wireFile: string): Promise<string> {
231	  try {
232	    const stream = fs.createReadStream(wireFile, { encoding: "utf-8" });
233	    const rl = readline.createInterface({ input: stream, crlfDelay: Infinity });
234	
235	    for await (const line of rl) {
236	      if (!line.trim()) {
237	        continue;
238	      }
239	
240	      try {
241	        const record = JSON.parse(line);
242	        if (record.message?.type !== "TurnBegin") {
243	          continue;
244	        }
245	
246	        const userInput = record.message.payload?.user_input;
247	        const text = extractUserText(userInput);
248	        if (text) {
249	          rl.close();
250	          stream.destroy();
251	          return text;
252	        }
253	      } catch {
254	        continue;
255	      }
256	    }
257	  } catch (err) {
258	    log.storage("Failed to read wire file: %O", err);
259	  }
260	
261	  return "";
262	}
263	
264	// Text Extraction Helpers
265	function extractUserText(userInput: unknown): string {
266	  if (typeof userInput === "string") {
267	    return stripFileTags(userInput);
268	  }
269	
270	  if (Array.isArray(userInput)) {
271	    const textParts = (userInput as ContentPart[]).filter((p): p is ContentPart & { type: "text" } => p.type === "text").map((p) => p.text);
272	    return stripFileTags(textParts.join("\n"));
273	  }
274	
275	  return "";
276	}
277	
278	function stripFileTags(text: string): string {
279	  return text
280	    .replace(/<uploaded_files>[\s\S]*?<\/uploaded_files>\s*/g, "")
281	    .replace(/<document[^>]*>[\s\S]*?<\/document>\s*/g, "")
282	    .replace(/<image[^>]*>[\s\S]*?<\/image>\s*/g, "")
283	    .trim();
284	}
285	
286	/** Extract first non-empty user message from a Think session JSONL file. */
287	async function getFirstUserMessageFromThinkFile(filePath: string): Promise<string> {
288	  try {
289	    const stream = fs.createReadStream(filePath, { encoding: "utf-8" });
290	    const rl = readline.createInterface({ input: stream, crlfDelay: Infinity });
291	
292	    for await (const line of rl) {
293	      if (!line.trim()) {
294	        continue;
295	      }
296	
297	      try {
298	        const record = JSON.parse(line);
299	        if (record.role !== "user") {
300	          continue;
301	        }
302	
303	        const text = typeof record.content === "string" ? record.content : "";
304	        const stripped = stripFileTags(text);
305	        if (stripped) {
306	          rl.close();
307	          stream.destroy();
308	          return stripped;
309	        }
310	      } catch {
311	        continue;
312	      }
313	    }
314	  } catch (err) {
315	    log.storage("Failed to read think session file: %O", err);
316	  }
317	
318	  return "";
319	}
320	
321	// Fork Session
322	export async function forkSession(options: ForkSessionOptions): Promise<ForkSessionResult> {
323	  const { workDir, sourceSessionId, turnIndex } = options;
324	
325	  if (!UUID_REGEX.test(sourceSessionId)) {
326	    throw new Error(`Invalid session ID: ${sourceSessionId}`);
327	  }
328	
329	  if (turnIndex < 0) {
330	    throw new Error(`Invalid turn index: ${turnIndex}`);
331	  }
332	
333	  const sourceDir = ConsiliumPaths.sessionDir(workDir, sourceSessionId);
334	  const sourceWireFile = path.join(sourceDir, "wire.jsonl");
335	  const sourceContextFile = path.join(sourceDir, "context.jsonl");
336	
337	  // Verify source session exists
338	  try {
339	    await fsp.access(sourceWireFile);
340	  } catch {
341	    throw new Error(`Source session not found: ${sourceSessionId}`);
342	  }
343	
344	  // Create new session
345	  const newSessionId = crypto.randomUUID();
346	  const newSessionDir = ConsiliumPaths.sessionDir(workDir, newSessionId);
347	
348	  await fsp.mkdir(newSessionDir, { recursive: true });
349	
350	  // Truncate wire.jsonl at the specified turn
351	  const wireLines = await truncateWireAtTurn(sourceWireFile, turnIndex);
352	  if (wireLines.length === 0) {
353	    await fsp.rm(newSessionDir, { recursive: true, force: true });
354	    throw new Error(`Turn ${turnIndex} not found in session`);
355	  }
356	
357	  await fsp.writeFile(path.join(newSessionDir, "wire.jsonl"), wireLines.join("\n") + "\n");
358	
359	  // Truncate context.jsonl if it exists
360	  try {
361	    await fsp.access(sourceContextFile);
362	    const contextLines = await truncateContextAtTurn(sourceContextFile, turnIndex);
363	    if (contextLines.length > 0) {
364	      await fsp.writeFile(path.join(newSessionDir, "context.jsonl"), contextLines.join("\n") + "\n");
365	    }
366	  } catch {
367	    // context.jsonl doesn't exist or is empty, that's fine
368	  }
369	
370	  log.storage("Forked session %s -> %s at turn %d", sourceSessionId, newSessionId, turnIndex);
371	
372	  return {
373	    sessionId: newSessionId,
374	    sessionDir: newSessionDir,
375	  };
376	}
377	
378	/**
379	 * Truncate wire.jsonl to include only complete turns up to the specified turn index.
380	 * If the target turn is incomplete (no TurnEnd), it will be discarded to prevent
381	 * API errors from incomplete tool calls.
382	 */
383	async function truncateWireAtTurn(wireFile: string, turnIndex: number): Promise<string[]> {
384	  const lines: string[] = [];
385	  let turnCount = 0;
386	  let lastTurnEndIndex = -1;
387	
388	  const stream = fs.createReadStream(wireFile, { encoding: "utf-8" });
389	  const rl = readline.createInterface({ input: stream, crlfDelay: Infinity });
390	
391	  for await (const line of rl) {
392	    if (!line.trim()) {
393	      continue;
394	    }
395	
396	    try {
397	      const record = JSON.parse(line);
398	      const messageType = record.message?.type;
399	
400	      if (messageType === "TurnBegin") {
401	        if (turnCount > turnIndex) {
402	          break;
403	        }
404	        turnCount++;
405	      }
406	
407	      lines.push(line);
408	
409	      // Track the last TurnEnd position
410	      if (messageType === "TurnEnd" && turnCount === turnIndex + 1) {
411	        lastTurnEndIndex = lines.length;
412	        break;
413	      }
414	    } catch {
415	      if (turnCount > 0 && turnCount <= turnIndex + 1) {
416	        lines.push(line);
417	      }
418	    }
419	  }
